		void AssertCheckpoint(string lookupCode, string expectDisplayName, string expectParentCode)
		{
			SecurityCheckpoint checkpoint = securityInstance.FindCheckPoint(new CheckpointLookupKey(lookupCode));
			AssertNotNull(checkpoint);
			AssertEquals("Display Name", expectDisplayName, checkpoint.DisplayText);
			AssertEquals("Parent", expectParentCode, checkpoint.Parent.Code);
		}

		void AssertCheckpoint(string lookupCode, string expectDisplayName)
		{
			SecurityCheckpoint checkpoint = securityInstance.FindCheckPoint(new CheckpointLookupKey(lookupCode));
			AssertEquals("Display Name", expectDisplayName, checkpoint.DisplayText);
		}

		protected override void SetUp()
		{
			base.SetUp();
			GlbSecurityCollection securityCollection = new GlbSecurityCollection(GlbStaff.CurrentUser, new BusinessObjectFactory());
			securityInstance = new SecurityCore(securityCollection, GlbStaff.CurrentUser, Env.CurrentBranch.PK, Env.CurrentDepartment.PK, Env.CurrentCompany.PK);
		}

		SecurityCore securityInstance;
	}
